// ClaudeComments — render component for claude-comments@1.0.
//
// Per-paragraph comment surface. Targets the `margin` slot of
// document-centric@1.0. Reads paragraphs / comments / suggestion
// state from DocumentContext and dispatches all mutations through
// the same context — no local writes to sbrd_documents.
//
// Comments and replies are user-driven; Claude replies are
// generated by the Submit & Branch flow that document-canvas
// owns (which calls into DocumentContext.submitAndBranch). This
// component itself is Composer tier — the surface initiates a
// comment add, an edit, or a delete on user click; no autonomous
// model calls live here.
//
// Soft dependency on document-canvas@1.0: when a room mounts
// claude-comments without a document-canvas, RoomShell substitutes
// the document-source-needed empty-state template.

import { motion } from 'framer-motion'
import { MessageSquare, Sparkles, ArrowRight } from 'lucide-react'
import { CommentCard, ClaudeOriginCard, ClaudeSuggestionCard, SidebarSectionLabel } from './sbrd/cards'
import { useDocument } from '../../stores/DocumentContext'

const GOLD = '#B8A070'
const SUGGESTION = '#22C55E'

const staggerContainer = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.04, delayChildren: 0.08 } },
}

function ClaudeNoteCard({ note, onJump }) {
  return (
    <motion.div
      className="px-3 py-2.5 rounded-xl border"
      style={{ backgroundColor: `${SUGGESTION}08`, borderColor: `${SUGGESTION}20` }}
    >
      <div className="flex items-start gap-2">
        <Sparkles className="w-3 h-3 flex-shrink-0 mt-0.5" style={{ color: SUGGESTION }} />
        <p className="text-[11px] text-[#4A5568] leading-relaxed flex-1">{note}</p>
        {onJump && (
          <motion.button
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            onClick={onJump}
            className="p-1 rounded flex-shrink-0 transition-colors"
            style={{ color: `${SUGGESTION}80` }}
          >
            <ArrowRight className="w-3 h-3" />
          </motion.button>
        )}
      </div>
    </motion.div>
  )
}

export default function ClaudeComments() {
  const {
    paragraphs,
    counts,
    expandedComments,
    activeCommentId, setActiveCommentId,
    replyingTo, setReplyingTo,
    replyInputs, setReplyInputs,
    submittedReplies,
    setSelectedParagraph,
    toggleExpandedComment,
    submitReply,
    deleteComment,
    acceptOrigin,
    rejectOrigin,
    acceptSuggestion,
    rejectSuggestion,
  } = useDocument()

  const { pendingComments, pendingSuggestions } = counts

  return (
    <div className="px-1" style={{ fontFamily: 'system-ui, sans-serif' }}>
      <div data-tour="sbrd-comments" className="space-y-3">
        <div className="flex items-center gap-2">
          <MessageSquare className="w-3.5 h-3.5" style={{ color: GOLD }} />
          <SidebarSectionLabel
            label="Comments & Suggestions"
            count={pendingComments + pendingSuggestions}
          />
        </div>

        {pendingSuggestions > 0 && (
          <>
            <SidebarSectionLabel label="Claude Suggestions" count={pendingSuggestions} />
            <motion.div variants={staggerContainer} initial="hidden" animate="show" className="space-y-2">
              {paragraphs.filter(p => p.claudeOrigin).map(para => (
                <ClaudeOriginCard
                  key={`origin-${para.id}`}
                  onJump={() => setSelectedParagraph(para.id)}
                  onAccept={() => acceptOrigin(para.id)}
                  onReject={() => rejectOrigin(para.id)}
                />
              ))}
              {paragraphs.filter(p => p.claudeSuggestions?.length > 0).flatMap(para =>
                para.claudeSuggestions.map(sugg => (
                  <ClaudeSuggestionCard
                    key={sugg.id}
                    suggestion={sugg}
                    onJump={() => setSelectedParagraph(para.id)}
                    onAccept={() => acceptSuggestion(para.id, sugg.id)}
                    onReject={() => rejectSuggestion(para.id, sugg.id)}
                  />
                )),
              )}
            </motion.div>
          </>
        )}

        <SidebarSectionLabel label="Comments" count={pendingComments} />
        <motion.div variants={staggerContainer} initial="hidden" animate="show" className="space-y-2">
          {paragraphs.filter(p => p.comments?.length > 0).flatMap(para =>
            para.comments.map(comment => (
              <CommentCard
                key={comment.id}
                comment={comment}
                expanded={expandedComments.has(comment.id)}
                isActive={activeCommentId === comment.id}
                onToggle={() => toggleExpandedComment(comment.id)}
                onActivate={() => setActiveCommentId(prev => prev === comment.id ? null : comment.id)}
                onJump={() => setSelectedParagraph(para.id)}
                onDelete={() => deleteComment(para.id, comment.id)}
                replyingTo={replyingTo}
                setReplyingTo={setReplyingTo}
                replyInput={replyInputs[comment.id] || ''}
                onReplyChange={v => setReplyInputs(prev => ({ ...prev, [comment.id]: v }))}
                submittedReplies={submittedReplies[comment.id] || []}
                onSubmitReply={() => submitReply(comment.id)}
              />
            )),
          )}
          {paragraphs.filter(p => p.claudeNote).map(para => (
            <ClaudeNoteCard
              key={`note-${para.id}`}
              note={para.claudeNote}
              onJump={() => setSelectedParagraph(para.id)}
            />
          ))}
          {pendingComments === 0 && !paragraphs.some(p => p.claudeNote) && (
            <p className="text-[11px] text-[#6B7C93] py-3 leading-relaxed">
              {pendingSuggestions === 0
                ? 'No comments yet. Highlight text then press Ctrl+Alt+M to annotate.'
                : 'No user comments yet.'}
            </p>
          )}
        </motion.div>
      </div>
    </div>
  )
}
